-- Seed the Custom Order content page. Mirrors CUSTOM_ORDER_DEFAULT_FIELDS in
-- dashboard/src/lib/data/content.ts. `on conflict do nothing` keeps this safe to
-- re-run and preserves any admin edits made through the dashboard.
insert into public.content_pages (slug, title, fields, updated_at) values
  ('custom-order', 'Custom Order', '{"eyebrow":"Bespoke","heroTitle":"Made For You Alone","heroSubtitle":"You imagined something the world doesn''t have yet — be proud of that. Share your idea and our craftsmen will forge it into a piece that is yours, and yours alone.","heroImage":"/img.png","galleryItems":[{"imageUrl":"/2.jpg.jpeg","caption":"Bespoke Dimensions"},{"imageUrl":"/6.jpg.jpeg","caption":"Custom Finishes"},{"imageUrl":"/9.jpg.jpeg","caption":"Industrial Craftsmanship"}],"steps":[{"title":"Share Your Vision","description":"Describe your idea, dimensions and finish — and upload any sketches or reference images that inspire you."},{"title":"Design & Refine","description":"Our team turns your concept into a precise blueprint and digital model, sent back for your approval."},{"title":"Forged in Steel","description":"Skilled artisans craft your piece from high-grade raw metal, entirely by hand in our Lahore workshop."},{"title":"Delivered to You","description":"Your one-of-a-kind piece is carefully packed and shipped directly to your space."}],"formHeading":"Start Your Commission","formSubheading":"Tell us what you have in mind"}'::jsonb, '2026-07-08T00:00:00.000Z')
on conflict (slug) do nothing;
